SELECT payload,payload::text FROM (SELECT jsonb_build_object('session_user',session_user::text,'current_user',current_user::text,'role',current_setting('role'),'isolation',current_setting('transaction_isolation'),'read_only',current_setting('transaction_read_only'),'timezone',current_setting('TimeZone'),'search_path',current_setting('search_path'),'server_version_num',current_setting('server_version_num'),'server_version',current_setting('server_version'),'database',current_database(),'actor',NULLIF(current_setting('hephaestus.actor_id',true),''),'request',NULLIF(current_setting('hephaestus.request_id',true),''),'subject_type',NULLIF(current_setting('hephaestus.subject_type',true),''),'occurrence',NULLIF(current_setting('hephaestus.occurrence_id',true),'')) AS payload) AS capture